@@ -0,0 +1,18 @@
+// Kitchen sites and their storage locations.
+import { AppError } from "../errors.js";
+
+/** The default site when none is named. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id = DEFAULT_SITE) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** Location ids belonging to `site` (validates `site`). */
+export function siteLocations(store, site = DEFAULT_SITE) {
+  getSite(store, site);
+  return new Set((store.data.locations ?? []).filter((l) => l.site === site).map((l) => l.id));
+}
